// Ported from the Node app's Sequelize model VehicleTracker (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class VehicleTrackerConfiguration : IEntityTypeConfiguration<VehicleTracker>
{
    public void Configure(EntityTypeBuilder<VehicleTracker> builder)
    {
        builder.ToTable("vehicle_trackers");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.VehicleId).HasColumnName("vehicle_id");
        builder.Property(e => e.ApiKey).HasColumnName("api_key").HasColumnType("nvarchar(64)").HasMaxLength(64).IsRequired();
        builder.HasIndex(e => e.VehicleId).IsUnique();
        builder.HasIndex(e => e.ApiKey).IsUnique();
        builder.HasOne(e => e.Vehicle).WithOne(p => p.VehicleTracker).HasForeignKey<VehicleTracker>(e => e.VehicleId).OnDelete(DeleteBehavior.NoAction);
    }
}
